<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import AuthLayout from '@/layouts/AuthLayout.vue'
import http, { getErrorMessage } from '@/api/http'

const router = useRouter(); const username = ref(''); const email = ref(''); const password = ref(''); const confirm = ref(''); const error = ref(''); const loading = ref(false); const submitted = ref(false); const created = ref(false)
const valid = () => /^[a-zA-Z0-9_.-]{3,50}$/.test(username.value) && /.+@.+\..+/.test(email.value) && /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/.test(password.value) && password.value === confirm.value
async function submit() { submitted.value = true; if (!valid()) return; loading.value = true; error.value = ''; try { await http.post('/auth/register', { username: username.value, email: email.value, password: password.value }); created.value = true } catch (e) { error.value = getErrorMessage(e) } finally { loading.value = false } }
</script>
<template><AuthLayout><template v-if="created"><p class="eyebrow">Cuenta creada</p><h1>¡Todo listo!</h1><p class="intro">Tu cuenta se creó correctamente como cliente. Ya puedes iniciar sesión y comenzar a usar el portal.</p><p class="notice success">Revisa que tu correo y contraseña estén guardados en un lugar seguro.</p><button class="primary-button" @click="router.push('/login')">Ir a iniciar sesión →</button></template><template v-else><p class="eyebrow">Nuevo acceso</p><h1>Crea tu cuenta</h1><p class="intro">Regístrate para consultar y dar seguimiento a los servicios de tu vehículo.</p><p v-if="error" class="notice error">{{ error }}</p><form class="form-stack" novalidate @submit.prevent="submit"><label class="field">Nombre de usuario<input v-model.trim="username" class="input no-icon" placeholder="Ej. ana.garcia" /><span v-if="submitted && !/^[a-zA-Z0-9_.-]{3,50}$/.test(username)" class="field-error">Usa de 3 a 50 caracteres válidos.</span></label><label class="field">Correo electrónico<input v-model.trim="email" class="input no-icon" type="email" placeholder="tu@correo.com" /><span v-if="submitted && !/.+@.+\..+/.test(email)" class="field-error">Ingresa un correo válido.</span></label><label class="field">Contraseña<input v-model="password" class="input no-icon" type="password" placeholder="Crea una contraseña" /><span v-if="submitted && !/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/.test(password)" class="field-error">Incluye 8 caracteres, mayúscula, minúscula y número.</span></label><label class="field">Confirmar contraseña<input v-model="confirm" class="input no-icon" type="password" placeholder="Repite la contraseña" /><span v-if="submitted && confirm !== password" class="field-error">Las contraseñas no coinciden.</span></label><button class="primary-button" type="submit" :disabled="loading">{{ loading ? 'Creando cuenta…' : 'Crear cuenta →' }}</button></form><div class="form-footer"><span class="subtle">¿Ya tienes cuenta?</span><RouterLink to="/login">Iniciar sesión</RouterLink></div></template></AuthLayout></template>
